import {createLiveAdvisor} from './live-advice-view.js';
import {mountBoardOdds} from './board-odds.js';
import {handStrength} from './hand-strength.js';
import {mountAudio} from './audio.js';
import {streetReviewHTML} from './street-review-view.js';
import {winnerHTML,rankingHTML} from './round-result.js';
import {actionControlsHTML,toggleBetPanel,updateBetPanel} from './bet-sizing.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const audio=mountAudio($('#audio-controls'));
const boardCalculator=mountBoardOdds($('#board-odds'));
const liveAdvisor=createLiveAdvisor();
const roomParam=new URL(location.href).searchParams.get('room');let inviteOrigin=location.origin;
let id=roomParam,token=id?localStorage.getItem('poker-room-'+id):null,state=null,painted=-1,busy=false,showStrength=false,lastHand=null,polling=false;
const suits={s:'♠',h:'♥',d:'♦',c:'♣'};
const card=c=>c?`<span class="card ${'hd'.includes(c[1])?'red':''}" aria-label="${esc(c[0])} ${suits[c[1]]}"><span>${c[0]==='T'?'10':c[0]}</span><span class="suit">${suits[c[1]]}</span></span>`:'<span class="card back" aria-label="Hidden card"></span>';
const n=v=>Number(v).toLocaleString('en-US');
async function api(path,body){const res=await fetch(path,{method:body?'POST':'GET',headers:{...(body?{'Content-Type':'application/json'}:{}),...(token?{Authorization:'Bearer '+token}:{})},body:body?JSON.stringify(body):undefined,cache:'no-store'});const data=await res.json();if(!res.ok)throw Error(data.error||'Could not reach the table.');return data;}
function inviteURL(){const url=new URL(inviteOrigin);url.pathname='/';url.searchParams.set('room',id);return url.href;}
function inviteMarkup(){return `<label for="invite-link">Friend invite</label><input id="invite-link" class="invite-url" readonly value="${esc(inviteURL())}"><p class="small-note">${inviteOrigin.startsWith('https:')?'This private invite works over the internet. Share it only with your friend.':'This invite works on the same Wi-Fi. A localhost link only works on this Mac.'}</p>`;}
async function copyInvite(){try{await navigator.clipboard.writeText(inviteURL());$('#error').textContent='Invite copied.';}catch{$('#error').innerHTML=inviteMarkup();}}
$('#join-button').textContent=id?'Join friend’s table':'Open a table';if(id)$('#welcome').textContent='Your seat is waiting. Choose your table name.';
$('#join-form').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;busy=true;$('#join-button').disabled=true;try{const result=await api(id?'/api/rooms/'+id+'/join':'/api/rooms',{name:$('#player-name').value});id=result.id;token=result.token;localStorage.setItem('poker-room-'+id,token);history.replaceState({},'', '/?room='+id);$('#error').textContent='';await refresh();}catch(e){$('#error').textContent=e.message;}finally{busy=false;$('#join-button').disabled=false;}});
async function send(type,amount){if(busy)return;busy=true;try{state=await api('/api/rooms/'+id+'/action',{type,amount,hand:state?.game?.hand,revision:state?.revision});$('#error').textContent='';render();}catch(e){$('#error').textContent=e.message;await refresh();}finally{busy=false;}}
$('#room-lobby').addEventListener('click',e=>{if(e.target.closest('[data-start]'))send('start');if(e.target.closest('[data-copy]'))copyInvite();});
const renameDialog=$('#rename-dialog');
$('#rename-player').addEventListener('click',()=>{if(!state)return;$('#new-player-name').value=state.members.find(m=>m.seat===state.seat).name;$('#rename-error').textContent='';renameDialog.showModal();$('#new-player-name').focus();});
$('#cancel-rename').addEventListener('click',()=>renameDialog.close());
$('#rename-form').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;busy=true;const button=e.submitter;button.disabled=true;try{state=await api('/api/rooms/'+id+'/action',{type:'rename',name:$('#new-player-name').value});render();renameDialog.close();}catch(error){$('#rename-error').textContent=error.message;}finally{busy=false;button.disabled=false;}});
$('#invite').addEventListener('click',copyInvite);$('#pause').addEventListener('click',()=>send(state.paused?'resume':'pause'));
$('#decision').addEventListener('click',e=>{if(toggleBetPanel($('#decision'),e.target))return;const preset=e.target.closest('[data-bet-size]');if(preset){$('#raise-amount').value=preset.dataset.betSize;updateSizing();return;}const button=e.target.closest('[data-action]');if(button)send(button.dataset.action,button.dataset.action==='raise'?Number($('#raise-amount').value):undefined);});
function updateSizing(source){if(state?.game?.legal){const g=state.game;updateBetPanel($('#decision'),g.legal,g.pot,g.currentBet??Math.max(...g.players.map(p=>p.bet)),g.players[state.seat],source);}}
$('#decision').addEventListener('input',e=>{if(['raise-amount','raise-slider'].includes(e.target.id))updateSizing(e.target);});
$('#table').addEventListener('click',e=>{if(e.target.closest('[data-info]')){showStrength=!showStrength;renderStrength();e.target.closest('[data-info]').setAttribute('aria-expanded',String(showStrength));}});
function renderStrength(){const box=$('#strength');box.hidden=!showStrength;if(!showStrength||!state.game)return;const g=state.game,h=handStrength(g.players[state.seat].hole,g.board);box.innerHTML=`<strong>${esc(h.rank)} · percentile ≈ ${h.percentile}</strong><p>${g.board.length?'Current made-hand strength':'Starting-hand strength'}${g.players[state.seat].folded?' · folded cards':''}</p><small>${esc(h.basis)}</small>`;}
function render(){$('#rename-player').hidden=false;const g=state.game;$('#join-form').hidden=true;$('#room-lobby').hidden=false;$('#lobby').hidden=!!g;$('#game-ui').hidden=!g;$('#pause').hidden=!g||!state.host;$('#pause').textContent=state.paused?'Resume table':'Pause table';
 if(!g){$('#room-lobby').innerHTML=`<div class="friend-list">${state.members.map(m=>`<div>${esc(m.name)} · ${m.online?'connected':'reconnecting'}</div>`).join('')}</div>${inviteMarkup()}<button data-copy>Copy invite</button>${state.host?`<button class="primary" data-start ${state.members.length<2?'disabled':''}>Start together</button>`:'<p>Waiting for your friend to start.</p>'}`;return;}
 boardCalculator.update({hole:g.players[state.seat].hole,board:g.board,complete:g.street==='complete'});
 audio.update({room:id,hand:g.hand,street:g.street,actor:g.actor,seat:state.seat,paused:state.paused,actionCount:g.log.length});
 document.title=!state.paused&&g.street!=='complete'&&g.actor===state.seat?'Your turn · Next Hand':'Next Hand · Macau After Hours';
 if(lastHand!==g.hand){showStrength=false;lastHand=g.hand;}renderStrength();$('#hand-number').textContent='Hand '+g.hand;$('#street').textContent=g.street==='complete'?'Hand complete':g.street;$('#room-label').textContent='Shared table';
 $('#table').innerHTML=g.players.map((p,i)=>{const seat=(i-state.seat+6)%6;return `<div class="seat seat-${seat} ${p.folded?'folded':''} ${g.actor===i&&!state.paused?'active':''}"><div class="cards">${p.hole.map(card).join('')}${i===state.seat?`<button class="hand-info" data-info aria-label="Hand strength information" aria-expanded="${showStrength}" aria-controls="strength">i</button>`:''}</div><div class="seat-info"><div class="seat-name">${esc(p.name)}${i===g.dealer?'<span class="badge">D</span>':''}${i===g.smallBlind?'<span class="badge blind">SB</span>':''}${i===g.bigBlind?'<span class="badge blind">BB</span>':''}</div><div class="seat-style">${i===state.seat?'You':esc(p.style)}</div><div class="stack">${n(p.stack)}</div></div><div class="seat-action">${esc(p.lastAction)}</div></div>`;}).join('')+`<div class="board"><div class="pot-label">${g.street==='complete'?'Pot awarded':'Pot'}</div><div class="pot-value">${n(g.pot)}</div><div class="cards">${Array.from({length:5},(_,i)=>g.board[i]?card(g.board[i]):'<span class="card empty">·</span>').join('')}</div></div>`;
 const me=g.players[state.seat],l=g.legal;
 if(g.street==='complete')$('#decision').innerHTML=`${winnerHTML(state.review?.result)}<button class="primary" data-action="ready" ${state.ready.includes(state.seat)?'disabled':''}>${state.ready.includes(state.seat)?'Ready · waiting for friend':'Ready for next hand →'}</button><p class="small-note">The next hand starts when you are both ready.</p>`;
 else if(state.paused)$('#decision').innerHTML='<h2>Table paused</h2><p class="waiting">The host can resume the shared game.</p>';
 else if(g.actor!==state.seat)$('#decision').innerHTML=`<h2>${me.folded?'You folded.':`${esc(g.players[g.actor].name)}’s turn`}</h2><p class="waiting">${me.folded?'Watch the hand finish, then compare the revealed cards.':'Your actions appear when it is your turn.'}</p>`;
 else {const currentBet=g.currentBet??Math.max(...g.players.map(p=>p.bet));$('#decision').innerHTML=`<h2>Your turn</h2><p class="waiting">Pot: <strong>${n(g.pot)}</strong> · Your stack: <strong>${n(me.stack)}</strong><br>${l.canCheck?'Nothing to call — checking costs 0.':`Call <strong>${n(l.call)}</strong> more to stay in.`}</p>${actionControlsHTML(l,g.pot,currentBet,me)}`;}

 liveAdvisor($('#decision'),g,state.seat,l,!state.paused&&g.street!=='complete'&&g.actor===state.seat);
 const review=state.review;$('#review').hidden=!review;if(review){$('#review').innerHTML=`${rankingHTML(review.result,card)}<div class="review compact-review"><h2>Overall play</h2><p><strong>${esc(review.comparison.result)}</strong> · ${n(me.stack-me.startStack)} chips</p><p>${esc(review.overall)}</p><div class="review-sections"><section><h3>What went well</h3><p>${esc(review.wentWell)}</p></section><section><h3>Decisions to revisit</h3><p><strong>${esc(review.cue.title)}</strong></p><p>${esc(review.cue.body)}</p><p>${esc(review.cue.next)}</p></section></div>${streetReviewHTML(review.streets,card)}<p class="small-note">${esc(review.comparison.note)}</p></div>`;}
 $('#players').innerHTML=g.players.map((p,i)=>{const actions=g.log.filter(t=>t.startsWith(p.name+': '));const hand=review?.hands.find(h=>h.name===p.name);return `<li class="player-read ${i===state.seat?'read-you':''}"><div class="read-heading"><strong>${esc(p.name)}</strong><span>${esc(p.style)}</span></div><p class="read-actions">${actions.slice(-2).map(t=>esc(t.slice(p.name.length+2))).join(' · ')||'Waiting to act'}</p>${hand?`<div class="read-result"><span>${hand.hole.map(card).join('')}</span><strong>${esc(hand.rank)}</strong></div><p class="read-insight">${hand.winner?'Won chips':hand.folded?'Folded':'Showdown'}${hand.hypothetical?' · final-board comparison':''}</p>`:''}<details><summary>Actions${hand?.bestFive.length?' & best five':''}</summary><p class="small-note">${actions.map(esc).join('<br>')}</p>${hand?.bestFive.length?`<div class="cards">${hand.bestFive.map(card).join('')}</div>`:''}</details></li>`;}).join('');painted=state.revision;
}
async function refresh(){if(!id||!token||polling)return;polling=true;try{state=await api('/api/rooms/'+id);$('#connection').textContent=state.members.some(m=>!m.online)?'Waiting for a player to reconnect · bot play is paused':'Connected · shared table';$('#connection').classList.remove('connection-offline');if(state.revision!==painted||!state.game)render();}catch(e){$('#connection').textContent='Disconnected · reconnecting';$('#connection').classList.add('connection-offline');$('#error').textContent=e.message;}finally{polling=false;}}
try{const local=await api('/api/local');inviteOrigin=local.inviteBase||(['localhost','127.0.0.1','[::1]'].includes(location.hostname)?local.addresses[0]:null)||location.origin;}catch{}
if(token)refresh();setInterval(refresh,800);
